        // slides) in loading form: the common result, so nothing moves.
        <div aria-busy='true' className='relative w-full max-w-full flex flex-col gap-4'>
          <SectionHeader
            title={title}
            subtitle={subtitle}
            inlineActions
            actions={
              <>
                <Skeleton className='size-8 rounded-md' />
                <Skeleton className='size-8 rounded-md' />
              </>
            }
          />
          <div className='overflow-hidden'>
            <div className='flex -ml-4'>
              {Array.from({ length: 4 }).map((_, index) => (
                <div key={index} className='min-w-0 shrink-0 grow-0 basis-full pl-4 xs:basis-1/2 md:basis-1/3 lg:basis-1/4'>
                  <SnapshotCardSkeleton />
                </div>
              ))}
            </div>
          </div>
        </div>
